'use strict';
const $=s=>document.querySelector(s),canvas=$('#canvas'),params=new URLSearchParams(location.search),embedded=params.get('embedded')==='1';let presenting=!embedded;if(embedded){document.documentElement.classList.add('embedded');}
const engine=new BABYLON.Engine(canvas,true,{preserveDrawingBuffer:true,stencil:true});engine.setHardwareScalingLevel(1/Math.min(devicePixelRatio,2));
const scene=new BABYLON.Scene(engine);scene.useRightHandedSystem=true;scene.clearColor=embedded?new BABYLON.Color4(0,0,0,0):new BABYLON.Color4(.063,.075,.086,1);
const camera=new BABYLON.ArcRotateCamera('camera',-Math.PI/2,1.42,1.6,new BABYLON.Vector3(0,.56,0),scene);camera.lowerBetaLimit=camera.upperBetaLimit=1.42;camera.lowerRadiusLimit=.6;camera.upperRadiusLimit=3;camera.minZ=.01;camera.wheelDeltaPercentage=.025;camera.attachControl(canvas,true);camera.panningSensibility=0;
new BABYLON.HemisphericLight('ambient',new BABYLON.Vector3(0,1,0),scene).intensity=.8;
const key=new BABYLON.DirectionalLight('key',new BABYLON.Vector3(.5,-.7,.7),scene);key.intensity=2.2;const fill=new BABYLON.DirectionalLight('fill',new BABYLON.Vector3(-.6,-.2,.5),scene);fill.intensity=.8;
let pack,guard,active=null,variant='zero',phase='guard',start=0,paused=false,pausedAt=0,returnAt=0,returnWeight=0,lastDanceWeight=0;const fade=.35;let duration=0;window.review={ready:false};
function weight(g,w){g.setWeightForAllAnimatables(w);if(g===active)lastDanceWeight=w}
function group(){return pack.animationGroups.find(g=>g.name===(variant==='zero'?'Dance_Zero':'Dance_Original'))}
function play(clipName=null){if(!pack)return;for(const g of pack.animationGroups)if(g!==guard)g.stop();active=clipName?pack.animationGroups.find(g=>g.name===clipName):group();if(!active)return;duration=(active.to-active.from)/60;active.start(false,1,active.from,active.to);weight(active,0);weight(guard,1);start=performance.now();phase='dance';paused=false;$('#pause').textContent='Пауза';$('#play').textContent='Ещё раз'}
function returnGuard(){if(phase==='guard')return;returnAt=performance.now();returnWeight=lastDanceWeight;phase='return';paused=false;$('#pause').textContent='Пауза'}
function setVariant(v){variant=v;$('#zero').classList.toggle('active',v==='zero');$('#original').classList.toggle('active',v==='original');if(phase==='dance'){const fraction=+$('#progress').value/1000,wasPaused=paused;play();active.goToFrame(active.from+fraction*duration*60);start=performance.now()-fraction*duration*1000;if(wasPaused){weight(active,1);weight(guard,0);active.pause();paused=true;pausedAt=performance.now();$('#pause').textContent='Продолжить'}}}
const ease=x=>{x=Math.max(0,Math.min(1,x));return x*x*(3-2*x)};
function tick(now){if(!pack||paused)return;if(phase==='dance'){
 const t=(now-start)/1000,w=ease(t/fade)*ease((duration-t)/fade);weight(active,w);weight(guard,1-w);$('#progress').value=Math.round(Math.min(1,t/duration)*1000);if(t>=duration){weight(guard,1);active.stop();active=null;phase='guard';if(embedded)parent.postMessage({type:'lf-preview-finished'},location.origin);}
 }else if(phase==='return'){const w=returnWeight*(1-ease((now-returnAt)/1000/fade));weight(active,w);weight(guard,1-w);if(w<=0){active?.stop();active=null;phase='guard';if(embedded)parent.postMessage({type:'lf-preview-finished'},location.origin);}}
 window.review.phase=phase;window.review.variant=variant;document.body.dataset.review=JSON.stringify(window.review);
}
$('#play').onclick=()=>play();$('#guard').onclick=returnGuard;$('#zero').onclick=()=>setVariant('zero');$('#original').onclick=()=>setVariant('original');
$('#pause').onclick=()=>{if(!active)return;paused=!paused;if(paused){pausedAt=performance.now();active.pause()}else{const elapsed=performance.now()-pausedAt;start+=elapsed;returnAt+=elapsed;active.restart()}$('#pause').textContent=paused?'Продолжить':'Пауза'};
$('#progress').oninput=()=>{if(phase!=='dance')play();const t=+$('#progress').value/1000*duration;start=performance.now()-t*1000;active.goToFrame(active.from+t*60);weight(active,1);weight(guard,0);active.pause();paused=true;pausedAt=performance.now();$('#pause').textContent='Продолжить'};
window.addEventListener('resize',()=>engine.resize());engine.runRenderLoop(()=>{if(!presenting)return;tick(performance.now());document.body.dataset.controls=JSON.stringify({phase,paused,variant,progress:+$('#progress').value});scene.render()});
BABYLON.SceneLoader.ImportMeshAsync('', (params.get('review')==='legacy'?'./':'guard-v3/'), 'sailor.gltf',scene).then(result=>{
 pack=result;for(const g of pack.animationGroups)g.stop();guard=pack.animationGroups.find(g=>g.name==='Guard');if(!guard)throw Error('Нет исходной позы');guard.start(true);weight(guard,1);
 const meshes=result.meshes.filter(m=>m.getTotalVertices()>0);const influencers=meshes.map(m=>m.numBoneInfluencers);if(influencers.some(n=>n!==8))throw Error('Проигрыватель не сохранил восемь каналов весов');
 for(const m of meshes){m.alwaysSelectAsActiveMesh=true;m.computeBonesUsingShaders=true;}scene.onAfterRenderObservable.addOnce(()=>{const m=meshes[0],b=m.getBoundingInfo().boundingBox;document.body.dataset.bounds=JSON.stringify({min:b.minimumWorld.asArray(),max:b.maximumWorld.asArray(),world:Array.from(m.getWorldMatrix().m),bones:m.skeleton?.bones.length});});window.review={ready:true,triangles:meshes.reduce((n,m)=>n+m.getTotalIndices()/3,0),influencers,animations:pack.animationGroups.map(g=>({name:g.name,from:g.from,to:g.to})),phase,variant};
 $('#status').textContent='Исходная детализация · 1,99 млн треугольников';$('#loading').hidden=true;document.querySelectorAll('button,input').forEach(b=>b.disabled=false);if(embedded)parent.postMessage({type:'lf-preview-ready'},location.origin);
}).catch(e=>{$('#loading').textContent='Не удалось открыть превью: '+e.message;window.review.error=String(e);if(embedded)parent.postMessage({type:'lf-preview-error'},location.origin);console.error(e)});

window.addEventListener('message',e=>{if(!embedded||e.origin!==location.origin||e.source!==parent)return;const d=e.data||{};if(d.type!=='lf-preview-command')return;if(d.command==='active'){presenting=!!d.active;if(!presenting&&pack)returnGuard();}if(d.command==='orbit'){camera.alpha=-Math.PI/2+(Number(d.yaw)||0)*Math.PI/180;camera.radius=Math.max(.6,Math.min(3,1.6*(Number(d.radius)||100)/100));}if(!pack)return;if(d.command==='pose')returnGuard();if(d.command==='motion'){if(d.kind==='dance')play('Dance_Zero');else if(d.kind==='punch')play('Attack_Punch');else if(d.kind==='kick')play('Attack_Kick');}});
